function draw(ctx,t,p){
  var W=960,H=540;
  var mode=p&&p.$mode==='explore'?'explore':'presentation';
  var finite=function(v,d){return typeof v==='number'&&isFinite(v)?v:d;};
  var clamp=function(v,a,b){return Math.max(a,Math.min(b,v));};
  var rawX=finite(p&&p.x,0), rawView=finite(p&&p.view,0);
  var x,view,scene,u;
  if(mode==='explore'){
    x=clamp(rawX,-2,2);
    view=clamp(Math.round(rawView),0,1);
    scene=Math.min(2,Math.floor(clamp(t,0,0.999999)*3));
    u=(clamp(t,0,0.999999)*3)%1;
  }else{
    var z=clamp(t,0,0.999999)*3;
    scene=Math.min(2,Math.floor(z)); u=z-scene;
    if(scene===0) x=-2+4*u;
    else if(scene===1) x=u<0.5?-1:-1+4*(u-0.5);
    else x=-2+4*u;
    view=scene===2&&u>0.48?1:0;
  }
  var f=function(q){return q*q*q-3*q;};
  var d=function(q){return 3*q*q-3;};
  var fx=f(x),dx=d(x);
  var cls=dx>0.0001?'递增':dx<-0.0001?'递减':'驻点：需看两侧符号';
  var extrema='';
  if(Math.abs(x+1)<0.08) extrema='x=-1：左正右负，局部极大';
  else if(Math.abs(x-1)<0.08) extrema='x=1：左负右正，局部极小';
  var plot={l:55,r:610,top:105,bot:395};
  var X=function(q){return plot.l+(q+2)/4*(plot.r-plot.l);};
  var Y=function(q){return 250-f(q)*55;};
  var text=function(s,px,py,size,color,align){ctx.fillStyle=color||'#17202a';ctx.font=(size||18)+'px sans-serif';ctx.textAlign=align||'left';ctx.textBaseline='middle';ctx.fillText(s,px,py);};
  var line=function(x1,y1,x2,y2,color,w){ctx.strokeStyle=color;ctx.lineWidth=w||2;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();};
  ctx.clearRect(0,0,W,H);ctx.fillStyle='#fbfcf7';ctx.fillRect(0,0,W,H);
  ctx.fillStyle='#eef4ef';ctx.fillRect(35,85,890,335);
  text(view===0?'函数图像视图':'导数符号带视图',650,105,18,'#41615a');
  text('f(x)=x³−3x',650,137,22,'#17202a');
  text('f′(x)=3x²−3',650,166,21,'#17202a');
  text('当前位置 x='+x.toFixed(2)+'， f(x)='+fx.toFixed(2),650,199,18,'#17202a');
  text('f′(x)='+dx.toFixed(2)+'，'+cls,650,226,18,dx>0?'#13795b':dx<0?'#b23a48':'#805500');
  if(extrema) text(extrema,650,253,18,'#805500');
  ctx.save();ctx.beginPath();ctx.rect(plot.l,plot.top,plot.r-plot.l,plot.bot-plot.top);ctx.clip();
  if(view===0){
    line(plot.l,250,plot.r,250,'#53636b',1.5);line(X(0),plot.top,X(0),plot.bot,'#53636b',1.5);
    for(var k=-2;k<=2;k++){line(X(k),246,X(k),254,'#53636b',1);text(String(k),X(k),270,15,'#53636b','center');}
    ctx.strokeStyle='#176b87';ctx.lineWidth=3;ctx.beginPath();
    for(var i=0;i<=240;i++){var q=-2+4*i/240,xx=X(q),yy=Y(q);if(i===0)ctx.moveTo(xx,yy);else ctx.lineTo(xx,yy);}ctx.stroke();
    var xa=X(x),ya=Y(x), slope=dx;
    var q1=-2,q2=2;line(X(q1),Y(x)+slope*(q1-x)*55,X(q2),Y(x)+slope*(q2-x)*55,'#d26a3a',2);
    ctx.fillStyle='#d22f45';ctx.beginPath();ctx.arc(xa,ya,6,0,Math.PI*2);ctx.fill();
    text('P('+x.toFixed(2)+','+fx.toFixed(2)+')',xa+10,ya-15,16,'#b12a3d');
    if(Math.abs(dx)<0.0001) text('水平切线',xa+12,ya+20,16,'#805500');
  }else{
    text('[-2,-1)',105,145,18,'#17202a','center');text('(-1,1)',330,145,18,'#17202a','center');text('(1,2]',535,145,18,'#17202a','center');
    ctx.fillStyle='#8bd3b5';ctx.fillRect(X(-2),180,X(-1)-X(-2),48);ctx.fillStyle='#f3b4b4';ctx.fillRect(X(-1),180,X(1)-X(-1),48);ctx.fillStyle='#8bd3b5';ctx.fillRect(X(1),180,X(2)-X(1),48);
    text('＋ 递增',X(-1)-110,204,18,'#155b43','center');text('− 递减',X(0),204,18,'#8a2634','center');text('＋ 递增',X(1)+105,204,18,'#155b43','center');
    line(X(-2),252,X(2),252,'#53636b',2);line(X(-1),244,X(-1),260,'#53636b',2);line(X(1),244,X(1),260,'#53636b',2);
    text('-1',X(-1),278,17,'#17202a','center');text('1',X(1),278,17,'#17202a','center');
  }
  ctx.restore();
  var px=X(x),py=Y(x);line(px,py,px,250,'#a24d38',1.5);line(px,250,px+dx*35,250,'#a24d38',2);
  text('切线斜率 = f′(x)',650,290,18,'#17202a');
  text('正：上升；负：下降；零：先检查两侧符号',650,320,17,'#41515b');
  text('播放演示：位置沿曲线移动，不把导数当作运动速度',650,350,16,'#53636b');
  text('控制：x 选择位置；视图切换函数图像/符号带',650,380,16,'#53636b');
  var title,caption;
  if(mode==='presentation'){
    if(scene===0){title='切线斜率与函数走势';caption='切线向上时导数为正，函数递增；切线向下时导数为负，函数递减。';}
    else if(scene===1){title='驻点与局部极值';caption='导数为零只说明切线水平；比较两侧符号，才能判断局部极值。';}
    else{title='用符号表概括增减';caption='符号表把曲线分段：正号上升，负号下降，变号处可判断极值。';}
  }else{
    title=view===0?'导数符号与函数走势：图像探索':'导数符号带：查看增减区间';
    caption=extrema?extrema+'；导数为零不能单独推出极值。':('当前位置 '+x.toFixed(2)+' 处函数'+cls+'，请结合两侧符号判断极值。');
  }
  return {metrics:{x:x,f:fx,derivative:dx,trend:cls,extrema:extrema||'当前点不是驻点',domain:'[-2,2]',view:view===0?'函数图像':'导数符号带'},controls:{x:x,view:view},disabled:{},title:title,caption:caption};
}
